function sanitizeRichText(value=""){
  const doc=new DOMParser().parseFromString(`<div>${value}</div>`,"text/html");
  const allowed=new Set(["DIV","P","BR","STRONG","B","EM","I","U","H2","H3","H4","UL","OL","LI","BLOCKQUOTE","SPAN","FONT","A"]);
  const styles=new Set(["font-family","font-size","text-align","color"]);
  [...doc.body.querySelectorAll("*")].forEach((node)=>{
    if(!allowed.has(node.tagName)){node.replaceWith(...node.childNodes);return;}
    [...node.attributes].forEach((attribute)=>{
      const name=attribute.name.toLowerCase();
      if(name==="style"){
        const safe=[...node.style].filter((key)=>styles.has(key)).map((key)=>`${key}:${node.style.getPropertyValue(key)}`).join(";");
        safe?node.setAttribute("style",safe):node.removeAttribute("style");
      }else if(node.tagName==="A"&&name==="href"){
        if(!/^(https?:|\/)/i.test(attribute.value))node.removeAttribute(name);
      }else if(!(node.tagName==="FONT"&&["face","size","color"].includes(name)))node.removeAttribute(name);
    });
    if(node.tagName==="A"&&node.hasAttribute("href")){node.setAttribute("target","_blank");node.setAttribute("rel","noopener");}
  });
  return doc.body.firstElementChild?.innerHTML||"";
}

