function testMetrics(row={}){const taken=Number(row.max_score)>0,correct=taken?Number(row.score||0):0,total=taken?Number(row.max_score):0,wrong=Math.max(0,total-correct),percent=total?Math.round(correct*100/total):0;return{taken,correct,wrong,total,percent};}
function trackableItems(area){return published().filter((entry)=>entry.area===area&&entry.item_type!=="report"&&(!published().some((candidate)=>candidate.parent_id===entry.id)||entry.body||entry.video_url||quizQuestions(entry.quiz_data).length));}
function knowledgeMapPage(item){const parent=state.items.find((entry)=>entry.id===item.parent_id),all=trackableItems(item.area),completed=all.filter((topic)=>state.progress.find((row)=>row.item_id===topic.id)?.completed).length,tested=all.filter((topic)=>testMetrics(state.progress.find((row)=>row.item_id===topic.id)).taken).length;const cards=all.map((topic)=>{const row=state.progress.find((entry)=>entry.item_id===topic.id)||{},status=progressStatus(row),test=testMetrics(row);return `<a class="map-topic-card clear-map-card" href="${topic.path}"><div class="map-topic-title"><span class="learning-status ${status.tone}">${status.label}</span><strong>${escapeHtml(topic.title)}</strong><small>${row.view_count||0} рет ашылды</small></div><div class="map-progress-cell"><span><b>${row.progress||0}%</b><i style="--progress:${row.progress||0}"></i></span></div><div class="map-test-cell ${test.taken?'taken':'not-taken'}">${test.taken?`<strong>${test.percent}%</strong><span><i>✓ ${test.correct} дұрыс</i><i>× ${test.wrong} қате</i></span>`:`<strong>Тапсырылмаған</strong><span>Тест нәтижесі жоқ</span>`}</div><em>→</em></a>`;}).join("");return shell(`${crumb(parent?.path||"/",parent?.title||"Басты бет")}<section class="page-head ${themeFor(item.area)}"><span class="orbit"><i></i><i></i><i></i></span><h1>${escapeHtml(item.title)}</h1></section>${!state.user?`<section class="map-login"><a class="primary-button" href="/login">Кіру</a></section>`:`<section class="knowledge-map-dashboard clear-map-dashboard"><header><div><span>Жалпы нәтиже</span><h2>${completed}/${all.length} сабақ аяқталды</h2></div><div><b>${tested}</b><span>Тапсырылған тест</span></div></header><div class="map-column-labels"><span>Сабақ және күйі</span><span>Прогресс</span><span>Тест нәтижесі</span></div><div class="map-topic-list">${cards||`<p class="resource-empty">Тақырыптар жоқ</p>`}</div></section>`}`);}

function resourceKind(resource){const mime=(resource.mime_type||"").toLowerCase(),name=(resource.filename||"").toLowerCase();if(mime.startsWith("image/"))return"image";if(mime.includes("pdf")||name.endsWith(".pdf"))return"pdf";if(mime.startsWith("video/"))return"video";if(mime.startsWith("audio/"))return"audio";if(/\.(doc|docx)$/.test(name))return"doc";if(/\.(ppt|pptx)$/.test(name))return"ppt";if(/\.(xls|xlsx)$/.test(name))return"xls";return"file";}
function safeExternalUrl(value){try{const url=new URL(value);return ["https:","http:"].includes(url.protocol)?url.href:"";}catch{return"";}}
function youtubeEmbedUrl(value=""){try{const url=new URL(value),host=url.hostname.replace(/^www\./,"");let id="";if(host==="youtu.be")id=url.pathname.split("/")[1]||"";else if(host==="youtube.com"||host==="m.youtube.com"){if(url.pathname==="/watch")id=url.searchParams.get("v")||"";else if(/^\/(embed|shorts)\//.test(url.pathname))id=url.pathname.split("/")[2]||"";}return /^[\w-]{6,20}$/.test(id)?`https://www.youtube-nocookie.com/embed/${id}`:"";}catch{return"";}}
function resourcePreview(resource,admin){if(/\.(docx|pptx)$/i.test(resource.filename||""))return `<div id="office-reader" class="office-reader" tabindex="0" aria-label="Материал мазмұны"><div class="office-reader-status" role="status">Материал ашылуда…</div></div>`;const kind=resourceKind(resource);if(!resource.url)return `<div class="resource-preview document"><span>${kind.toUpperCase()}</span></div>`;const url=escapeHtml(resource.url);if(kind==='image')return `<img class="file-image" src="${url}" alt="${escapeHtml(resource.filename)}"/>`;if(kind==='pdf')return `<iframe class="file-frame" src="${url}" title="${escapeHtml(resource.filename)}"></iframe>`;if(kind==='video')return `<video src="${url}" controls></video>`;if(kind==='audio')return `<audio src="${url}" controls></audio>`;return `<div class="document-empty"><strong>${escapeHtml(resource.filename)}</strong><p>Бұл құжатты құрылғыңыздағы Word немесе PowerPoint арқылы ашу үшін жүктеп алыңыз.</p></div>`;}
function downloadUrl(resource){return resource.url+(resource.url.includes('?')?'&':'?')+'download='+encodeURIComponent(resource.filename);}
function resourceList(itemId,admin=false){const resources=state.resources[itemId]||[];return `<div class="resource-list">${resources.map(r=>`<article class="resource-card"><span class="file-type">${resourceKind(r).toUpperCase()}</span><strong>${escapeHtml(r.filename)}</strong><small>${formatSize(r.size)}</small><div class="material-actions"><button data-open-resource="${r.id}">Ашу</button><button data-download-resource="${r.id}">Жүктеп алу</button>${admin?`<button data-action="delete-resource" data-id="${r.id}" data-item="${itemId}" data-title="${escapeHtml(r.filename)}">Өшіру</button>`:''}</div></article>`).join('')||'<p>Файлдар жоқ</p>'}</div>`;}

function progressPanel(item){if(!state.user||state.user.role==="admin")return"";const row=state.progress.find((entry)=>entry.item_id===item.id)||{progress:0},status=progressStatus(row),test=testMetrics(row);return `<section class="learning-panel clear-learning-panel"><div class="learning-head"><div><span class="learning-status ${status.tone}">${status.label}</span><h2>Сабақ прогресі</h2></div><strong>${row.progress||0}%</strong></div><form id="progress-form" data-item="${item.id}"><input aria-label="Оқу прогресі" type="range" name="progress" min="0" max="100" value="${row.progress||0}"/><div class="progress-actions"><label><input type="checkbox" name="completed" ${row.completed?'checked':''}/> Сабақты аяқтадым</label><button class="primary-button compact" type="submit">Сақтау</button></div></form>${test.taken?`<div class="saved-score clear-saved-score"><div><span>Тест нәтижесі</span><strong>${test.percent}%</strong></div><div class="correct"><span>Дұрыс жауап</span><strong>${test.correct}</strong></div><div class="wrong"><span>Қате жауап</span><strong>${test.wrong}</strong></div><div><span>Тапсыру саны</span><strong>${row.attempt_count||1}</strong></div></div>`:""}</section>`;}
function quizBlock(item){const questions=quizQuestions(item.quiz_data).filter((quiz)=>Array.isArray(quiz.options)&&quiz.options.filter(Boolean).length>=2);if(!questions.length)return"";if(!state.user||state.user.role==="admin")return `<section class="quiz-card"><h2>Тест</h2><a class="primary-button compact" href="/login">Кіру</a></section>`;const row=state.progress.find((entry)=>entry.item_id===item.id)||{},test=testMetrics(row),answers=Array.isArray(row.quiz_answers)?row.quiz_answers:[];const result=test.taken?`<section class="quiz-result" aria-live="polite"><div class="quiz-result-score"><span>Соңғы нәтиже</span><strong>${test.percent}%</strong><small>${test.correct}/${test.total} ұпай</small></div><div class="quiz-result-metrics"><div class="correct"><span>✓</span><b>${test.correct}</b><small>Дұрыс жауап</small></div><div class="wrong"><span>×</span><b>${test.wrong}</b><small>Қате жауап</small></div><div><span>↻</span><b>${row.attempt_count||1}</b><small>Тапсыру саны</small></div></div><time>${formatDate(row.tested_at||row.updated_at)}</time></section>`:"";return `<section class="quiz-card clear-quiz-card"><div class="quiz-title"><div><span>Білімді тексеру</span><h2>Тест</h2></div><strong>${questions.length} сұрақ</strong></div>${result}<form id="quiz-form" data-item="${item.id}">${questions.map((quiz,qIndex)=>{const selected=Number.isInteger(Number(answers[qIndex]))?Number(answers[qIndex]):-1,correct=Number(quiz.correct_index||0);return `<fieldset data-correct="${correct}" class="${test.taken?'reviewed':''}"><legend><span>${qIndex+1}</span><strong>${escapeHtml(quiz.question)}</strong>${test.taken?`<em class="question-result ${selected===correct?'correct':'wrong'}">${selected===correct?'Дұрыс':'Қате'}</em>`:""}</legend>${quiz.options.map((option,index)=>option?`<label class="${test.taken&&index===correct?'answer-correct':''} ${test.taken&&index===selected&&selected!==correct?'answer-wrong':''}"><input type="radio" name="answer_${qIndex}" value="${index}" ${test.taken&&index===selected?'checked':''} required/><span>${escapeHtml(option)}${test.taken&&index===correct?`<small>Дұрыс жауап</small>`:""}${test.taken&&index===selected&&selected!==correct?`<small>Сіздің жауабыңыз</small>`:""}</span></label>`:"").join("")}</fieldset>`;}).join("")}<p class="form-error" id="quiz-error"></p><button class="primary-button compact" type="submit">${test.taken?'Қайта тапсыру':'Тапсыру'}</button></form></section>`;}
function detailPage(item){const parent=state.items.find((candidate)=>candidate.id===item.parent_id),youtube=youtubeEmbedUrl(item.video_url);return shell(`${crumb(parent?.path||"/",parent?.title||"Басты бет")}<article class="detail-sheet ${themeFor(item.area)}"><span class="detail-molecule"><i></i><i></i><i></i></span><h1>${escapeHtml(item.title)}</h1>${item.body?`<div class="detail-body rich-content">${sanitizeRichText(item.body)}</div>`:""}${youtube?`<section class="youtube-player"><iframe src="${youtube}" title="YouTube бейнесі" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe><a href="${escapeHtml(safeExternalUrl(item.video_url))}" target="_blank" rel="noopener">YouTube-та ашу ↗</a></section>`:item.video_url?`<a class="video-link" href="${escapeHtml(safeExternalUrl(item.video_url))}" target="_blank" rel="noopener"><span>▶</span> Бейнені ашу</a>`:""}${resourceList(item.id)}</article>${quizBlock(item)}${progressPanel(item)}`);}
function parentChain(item){const chain=[];let current=item;while(current?.parent_id){current=state.items.find((entry)=>entry.id===current.parent_id);if(!current)break;chain.unshift(current);}return chain;}

