function adminTree(parentId=null,depth=0){return state.items.filter((item)=>item.area===state.adminArea&&(item.parent_id||null)===parentId).sort((a,b)=>a.sort_order-b.sort_order).map((item,index,list)=>{const childType=item.item_type==="program"?"course":item.item_type==="course"?"module":item.item_type==="module"?"lesson":null,children=adminTree(item.id,depth+1);return `<li class="builder-node" style="--depth:${depth}"><div class="builder-row"><span class="builder-handle">⋮⋮</span><span class="builder-kind ${item.item_type}">${escapeHtml(ITEM_TYPE_LABELS[item.item_type]||"Сабақ")}</span><div class="builder-title"><strong>${escapeHtml(item.title)}</strong><small>${escapeHtml(item.path)}</small></div><span class="status-badge ${item.is_published?'published':'hidden'}">${item.is_published?'Жарияланған':'Жасырылған'}</span><div class="builder-actions">${childType?`<button data-action="add-child" data-parent="${item.id}" data-type="${childType}">+ ${escapeHtml(ITEM_TYPE_LABELS[childType])}</button>`:""}<button data-action="move-up" data-id="${item.id}" ${index===0?'disabled':''}>↑</button><button data-action="move-down" data-id="${item.id}" ${index===list.length-1?'disabled':''}>↓</button><button data-action="edit" data-id="${item.id}">Өңдеу</button><button class="danger-link" data-action="delete" data-id="${item.id}" data-title="${escapeHtml(item.title)}">Өшіру</button></div></div>${children?`<ul class="builder-children">${children}</ul>`:""}</li>`;}).join("");}
