function richTextEditor(body){return `<div class="rich-editor-field"><span class="field-label">Мәтіндік контент</span><div class="rich-toolbar" role="toolbar" aria-label="Мәтінді форматтау"><select data-rich-command="fontName" aria-label="Шрифт"><option value="Inter">Inter</option><option value="Arial">Arial</option><option value="Georgia">Georgia</option><option value="Courier New">Courier</option></select><select data-rich-command="fontSize" aria-label="Шрифт өлшемі"><option value="2">Кіші</option><option value="3" selected>Қалыпты</option><option value="4">Үлкен</option><option value="5">Өте үлкен</option></select><select data-rich-command="formatBlock" aria-label="Мәтін түрі"><option value="p">Абзац</option><option value="h2">Тақырып 2</option><option value="h3">Тақырып 3</option><option value="blockquote">Дәйексөз</option></select><button type="button" data-rich-command="bold" aria-label="Қалың"><b>B</b></button><button type="button" data-rich-command="italic" aria-label="Курсив"><i>I</i></button><button type="button" data-rich-command="underline" aria-label="Асты сызылған"><u>U</u></button><button type="button" data-rich-command="insertUnorderedList" aria-label="Маркерлі тізім">• Тізім</button><button type="button" data-rich-command="insertOrderedList" aria-label="Нөмірлі тізім">1. Тізім</button><button type="button" data-rich-command="justifyLeft" aria-label="Солға туралау">≡</button><button type="button" data-rich-command="justifyCenter" aria-label="Ортаға туралау">≡</button></div><div id="rich-body" class="rich-editor" contenteditable="true" role="textbox" aria-multiline="true" data-placeholder="Мәтін енгізіңіз">${sanitizeRichText(body)}</div></div>`;}
