function editorPanel(){const item=state.editing==="new"?{title:"",path:"",body:"",video_url:"",quiz_data:{},area:state.adminArea,parent_id:"",sort_order:state.items.filter((entry)=>entry.area===state.adminArea).length,is_published:true}:state.items.find((entry)=>entry.id===state.editing);if(!item)return"";const questions=quizQuestions(item.quiz_data);const parents=state.items.filter((entry)=>entry.area===item.area&&entry.id!==item.id);return `<aside class="editor-panel"><div class="editor-head"><h2>${state.editing==='new'?'Қосу':'Редакциялау'}</h2><button class="icon-button" data-action="close-editor">×</button></div><form id="content-form"><label>Бөлім атауы<input name="title" value="${escapeHtml(item.title)}" required/></label><label>URL<input name="path" value="${escapeHtml(item.path)}" required/></label><label>Бөлім<select name="area">${Object.entries(AREAS).map(([key,label])=>`<option value="${key}" ${item.area===key?'selected':''}>${label}</option>`).join("")}</select></label><label>Жоғарғы бөлім<select name="parent_id"><option value="">—</option>${parents.map((parent)=>`<option value="${parent.id}" ${item.parent_id===parent.id?'selected':''}>${escapeHtml(parent.title)}</option>`).join("")}</select></label><label>Орналасу реті<input type="number" name="sort_order" min="0" value="${item.sort_order}"/></label>${richTextEditor(item.body)}<label>Бейне сілтемесі<input type="url" name="video_url" value="${escapeHtml(item.video_url||"")}"/></label><fieldset class="quiz-editor"><legend>Тест</legend><div id="quiz-questions">${questions.map(quizQuestionEditor).join("")}</div><button class="add-question-button" type="button" data-action="add-question">+ Сұрақ қосу</button></fieldset>${state.editing!=="new"?`<fieldset class="upload-editor"><legend>Файлдар</legend>${resourceList(item.id,true)}<label class="file-drop">PDF, Word, PowerPoint немесе басқа файл жүктеу<input type="file" id="resource-file" accept="image/*,.pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.zip,video/*,audio/*"/></label></fieldset>`:`<p class="resource-empty">Файл қосу үшін алдымен бөлімді сақтаңыз</p>`}<label class="publish-control"><input type="checkbox" name="is_published" ${item.is_published?'checked':''}/> Жариялау</label><p class="form-error" id="content-error"></p><button class="primary-button" type="submit">Сақтау</button></form></aside>`;}
function lmsEditorPanel(){const parent=state.items.find((entry)=>entry.id===state.newParentId),item=state.editing==="new"?{title:"",path:"",body:"",video_url:"",quiz_data:{},area:parent?.area||state.adminArea,item_type:state.newItemType||"lesson",parent_id:parent?.id||null,sort_order:childrenOf(parent?.id).length,is_published:true}:state.items.find((entry)=>entry.id===state.editing);if(!item)return"";const questions=quizQuestions(item.quiz_data),parents=state.items.filter((entry)=>entry.area===item.area&&entry.id!==item.id);return `<aside class="editor-panel lms-editor"><div class="editor-head"><div><span class="admin-eyebrow">${escapeHtml(ITEM_TYPE_LABELS[item.item_type]||"Контент")}</span><h2>${state.editing==='new'?'Жаңа контент':'Контентті өңдеу'}</h2></div><button class="icon-button" data-action="close-editor">×</button></div><nav class="editor-tabs" aria-label="Редактор бөлімдері"><button type="button" class="active" data-editor-tab="main">Негізгі</button><button type="button" data-editor-tab="material">Материал</button><button type="button" data-editor-tab="test">Тест</button><button type="button" data-editor-tab="files">Файлдар</button></nav><form id="content-form"><section class="editor-step active" data-editor-step="main"><label>Атауы<input name="title" value="${escapeHtml(item.title)}" required/></label><label>URL<input name="path" value="${escapeHtml(item.path)}" required/></label><div class="editor-two-col"><label>Контент түрі<select name="item_type">${["program","course","module","lesson","report"].map((type)=>`<option value="${type}" ${item.item_type===type?'selected':''}>${ITEM_TYPE_LABELS[type]}</option>`).join("")}</select></label><label>Орналасу реті<input type="number" name="sort_order" min="0" value="${item.sort_order}"/></label></div><label>Жоғарғы бөлім<select name="parent_id"><option value="">—</option>${parents.map((entry)=>`<option value="${entry.id}" ${item.parent_id===entry.id?'selected':''}>${escapeHtml(entry.title)}</option>`).join("")}</select></label><input type="hidden" name="area" value="${item.area}"/><label class="publish-control"><input type="checkbox" name="is_published" ${item.is_published?'checked':''}/> Жариялау</label></section><section class="editor-step" data-editor-step="material">${richTextEditor(item.body)}<label>Бейне сілтемесі<input type="url" name="video_url" value="${escapeHtml(item.video_url||"")}"/></label></section><section class="editor-step" data-editor-step="test"><fieldset class="quiz-editor"><legend>Тест сұрақтары</legend><div id="quiz-questions">${questions.map(quizQuestionEditor).join("")}</div><button class="add-question-button" type="button" data-action="add-question">+ Сұрақ қосу</button></fieldset></section><section class="editor-step" data-editor-step="files">${state.editing!=="new"?`<fieldset class="upload-editor"><legend>Файлдар</legend>${resourceList(item.id,true)}<label class="file-drop">Файл жүктеу<input type="file" id="resource-file" accept="image/*,.pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.zip,video/*,audio/*"/></label></fieldset>`:`<div class="editor-save-first"><strong>Алдымен негізгі мәліметті сақтаңыз</strong><span>Сақтағаннан кейін файл жүктеу бірден ашылады.</span></div>`}</section><p class="form-error" id="content-error"></p><div class="editor-footer"><button type="button" data-action="close-editor">Жабу</button><button class="primary-button" type="submit">Сақтау</button></div></form></aside>`;}
function nodeStats(item){const all=descendantsOf(item.id),modules=all.filter((entry)=>entry.item_type==="module").length,lessons=all.filter((entry)=>entry.item_type==="lesson").length,hidden=all.filter((entry)=>!entry.is_published).length;return{modules,lessons,hidden};}
function friendlyAdminTree(parentId=null,depth=0){const list=state.items.filter((item)=>item.area===state.adminArea&&(item.parent_id||null)===parentId).sort((a,b)=>a.sort_order-b.sort_order);return list.map((item,index)=>{const type=item.item_type||"lesson",resourceOnly=item.content_mode==="resources",childType=resourceOnly?null:type==="program"?"course":type==="course"?"module":type==="module"?"lesson":null,direct=state.items.filter((entry)=>entry.parent_id===item.id),stats=nodeStats(item),collapsed=state.collapsed.has(item.id),selected=state.editing===item.id,questions=quizQuestions(item.quiz_data).length,indicators=[item.body?"Мәтін":"",item.video_url?"Бейне":"",questions?`${questions} тест`:"",state.resources[item.id]?.length?`${state.resources[item.id].length} файл`:""].filter(Boolean);const summary=resourceOnly?`${state.resources[item.id]?.length||0} файл · Құжаттар жинағы`:type==="program"?`${direct.filter((entry)=>entry.item_type==="course").length} курс · ${stats.modules} модуль · ${stats.lessons} сабақ`:type==="course"?`${stats.modules} модуль · ${stats.lessons} сабақ`:type==="module"?`${direct.length} сабақ`:indicators.join(" · ")||"Материал қосылмаған";return `<li class="builder-node builder-${type} ${resourceOnly?'builder-resources':''}" data-sort-id="${item.id}" data-parent-id="${item.parent_id||""}" style="--depth:${depth}"><div class="builder-row ${selected?'is-selected':''}"><button type="button" class="builder-handle" title="Жылжыту үшін сүйреңіз" aria-label="«${escapeHtml(item.title)}» орнын өзгерту">⠿</button>${direct.length&&!resourceOnly?`<button type="button" class="branch-toggle" data-action="toggle-branch" data-id="${item.id}" aria-expanded="${!collapsed}" aria-label="Тармақты ${collapsed?'ашу':'жабу'}">${collapsed?'›':'⌄'}</button>`:`<span class="branch-spacer"></span>`}<div class="builder-title"><span class="builder-kind ${resourceOnly?'resources':type}">${resourceOnly?'Құжаттар':escapeHtml(ITEM_TYPE_LABELS[type]||"Сабақ")}</span><strong>${escapeHtml(item.title)}</strong><small>${escapeHtml(summary)}</small></div><span class="status-badge ${item.is_published?'published':'hidden'}">${item.is_published?'Жарияланған':'Жасырылған'}</span><div class="builder-actions">${resourceOnly?`<button class="builder-add" data-action="manage-files" data-id="${item.id}">+ Файл жүктеу</button>`:childType?`<button class="builder-add" data-action="add-child" data-parent="${item.id}" data-type="${childType}">+ ${escapeHtml(ITEM_TYPE_LABELS[childType])}</button>`:""}<button class="builder-edit" data-action="edit" data-id="${item.id}">Өңдеу</button><div class="builder-more"><button type="button" class="more-button" aria-label="Қосымша әрекеттер">•••</button><div class="more-menu"><button data-action="move-up" data-id="${item.id}" ${index===0?'disabled':''}>Жоғары жылжыту</button><button data-action="move-down" data-id="${item.id}" ${index===list.length-1?'disabled':''}>Төмен жылжыту</button><button class="danger-link" data-action="delete" data-id="${item.id}" data-title="${escapeHtml(item.title)}">Өшіру</button></div></div></div></div>${direct.length&&!collapsed&&!resourceOnly?`<ul class="builder-children" data-sort-list data-parent-id="${item.id}">${friendlyAdminTree(item.id,depth+1)}</ul>`:""}</li>`;}).join("");}
function itemBreadcrumb(item){const parts=[];let current=item;while(current){parts.unshift(current.title);current=state.items.find((entry)=>entry.id===current.parent_id);}return parts.join(" / ");}
function friendlyLmsEditorPanel(){const parent=state.items.find((entry)=>entry.id===state.newParentId),item=state.editing==="new"?{title:"",path:"",body:"",video_url:"",quiz_data:{},area:parent?.area||state.adminArea,item_type:state.newItemType||"lesson",parent_id:parent?.id||null,sort_order:childrenOf(parent?.id).length,is_published:true}:state.items.find((entry)=>entry.id===state.editing);if(!item)return"";const questions=quizQuestions(item.quiz_data),parents=state.items.filter((entry)=>entry.area===item.area&&entry.id!==item.id),steps=[{id:"main",n:1,title:"Негізгі мәлімет",sub:"Атауы мен жариялануы",done:!!item.title},{id:"material",n:2,title:"Сабақ материалы",sub:"Мәтін және бейне",done:!!(item.body||item.video_url)},{id:"test",n:3,title:"Тест",sub:`${questions.length} сұрақ`,done:questions.length>0},{id:"files",n:4,title:"Файлдар",sub:`${state.allResources.filter(r=>r.item_id===item.id).length} файл`,done:state.allResources.filter(r=>r.item_id===item.id).length>0}];return `<aside class="editor-panel lms-editor friendly-editor"><div class="editor-head"><div><span class="admin-eyebrow">${escapeHtml(ITEM_TYPE_LABELS[item.item_type]||"Контент")}</span><h2>${state.editing==='new'?`Жаңа ${String(ITEM_TYPE_LABELS[item.item_type]||"контент").toLowerCase()} жасау`:`${escapeHtml(item.title)} өңдеу`}</h2><p>${escapeHtml(state.editing==='new'?(parent?itemBreadcrumb(parent):AREAS[item.area]):itemBreadcrumb(item))}</p></div><button class="icon-button" data-action="close-editor" aria-label="Жабу">×</button></div><nav class="editor-tabs editor-stepper" aria-label="Редактор қадамдары">${steps.map((step)=>`<button type="button" class="${state.editorTab===step.id?'active':''} ${step.done?'complete':''}" data-editor-tab="${step.id}"><b>${step.done?'✓':step.n}</b><span><strong>${step.title}</strong><small>${step.sub}</small></span></button>`).join("")}</nav><form id="content-form"><section class="editor-step" data-editor-step="main"><header class="editor-section-header"><span>01</span><div><h3>${escapeHtml(ITEM_TYPE_LABELS[item.item_type]||"Контент")} туралы</h3><p>Атауы мен жариялану күйі</p></div></header><label class="title-field">${escapeHtml(ITEM_TYPE_LABELS[item.item_type]||"Бөлім")} атауы<input name="title" value="${escapeHtml(item.title)}" required autofocus/></label><label class="publish-control large"><input type="checkbox" name="is_published" ${item.is_published?'checked':''}/><span><strong>Жариялау</strong><small>Пайдаланушыларға бірден көрінеді</small></span></label><details class="advanced-settings"><summary>Қосымша баптаулар</summary><label>URL<input name="path" value="${escapeHtml(item.path)}" required/></label><label>Жоғарғы бөлім<select name="parent_id">${!item.parent_id?`<option value="">—</option>`:""}${parents.map((entry)=>`<option value="${entry.id}" ${item.parent_id===entry.id?'selected':''}>${escapeHtml(entry.title)}</option>`).join("")}</select></label><label>Орналасу реті<input type="number" name="sort_order" min="0" value="${item.sort_order}"/></label></details><input type="hidden" name="area" value="${item.area}"/><input type="hidden" name="item_type" value="${item.item_type}"/></section><section class="editor-step" data-editor-step="material"><header class="editor-section-header"><span>02</span><div><h3>Оқу материалы</h3><p>Мәтін мен бейне қосыңыз</p></div></header>${richTextEditor(item.body)}<label>Кірістірілетін YouTube сілтемесі<input type="url" name="video_url" value="${escapeHtml(item.video_url||"")}"/></label></section><section class="editor-step" data-editor-step="test"><header class="editor-section-header"><span>03</span><div><h3>Білімді тексеру</h3><p>Сұрақтар мен дұрыс жауаптарды белгілеңіз</p></div></header><fieldset class="quiz-editor"><legend>${questions.length||0} сұрақ</legend><div id="quiz-questions">${questions.map(quizQuestionEditor).join("")}</div><button class="add-question-button" type="button" data-action="add-question">+ Жаңа сұрақ қосу</button></fieldset></section><section class="editor-step" data-editor-step="files"><header class="editor-section-header"><span>04</span><div><h3>Қосымша материалдар</h3><p>PDF, Word, PPT және басқа файлдар</p></div></header>${state.editing!=="new"?`<fieldset class="upload-editor"><legend>Жүктелген файлдар</legend>${resourceList(item.id,true)}<label class="file-drop">+ Файлдарды таңдаңыз<input type="file" id="resource-file" accept="image/*,.pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.zip,video/*,audio/*"/></label></fieldset>`:`<div class="editor-save-first"><strong>Алдымен негізгі мәліметті сақтаңыз</strong><span>Сақтағаннан кейін файлдар бөлімі ашылады.</span></div>`}</section><p class="form-error" id="content-error"></p><div class="editor-footer"><span>Өзгерістерді сақтаңыз</span><button type="button" data-action="close-editor">Бас тарту</button>${state.editing!=="new"?`<a class="preview-link" href="${escapeHtml(item.path)}" target="_blank">Көру ↗</a>`:""}<button class="primary-button" type="submit">Сақтау</button></div></form></aside>`;}
function resourceAwareEditorPanel(){let html=friendlyLmsEditorPanel();const item=state.editing==="new"?{content_mode:"curriculum"}:state.items.find((entry)=>entry.id===state.editing)||{},resourceOnly=item.content_mode==="resources",modeField=`<label class="content-mode-field">Бөлім форматы<select name="content_mode"><option value="curriculum" ${!resourceOnly?'selected':''}>Оқу курсы — модульдер мен сабақтар</option><option value="resources" ${resourceOnly?'selected':''}>Құжаттар жинағы — файл ұяшықтары</option></select><small>${resourceOnly?'Бұл бөлімде тек файлдар көрсетіледі':'Бұл бөлімде модульдер мен сабақтар көрсетіледі'}</small></label>`;html=html.replace('<label class="publish-control large">',`${modeField}<label class="publish-control large">`);if(resourceOnly){html=html.replace(/<button[^>]*data-editor-tab="material"[\s\S]*?<\/button>/,'').replace(/<button[^>]*data-editor-tab="test"[\s\S]*?<\/button>/,'').replace('editor-tabs editor-stepper','editor-tabs editor-stepper resource-stepper').replace('Сабақ материалы','Құжаттар');}return html;}
function friendlyLmsAdminPage(){if(state.user?.role!=="admin")return shell(`<section class="status-page"><span>403</span><h1>Қолжетім жоқ</h1><a class="primary-button" href="/login">Кіру</a></section>`);if(state.adminTab==="dashboard")return dashboardPage();if(state.adminTab==="design")return advancedThemePage();if(state.adminTab==="analytics")return analyticsPage();if(state.adminTab==="users")return adminUsersPage();const areaItems=state.items.filter((item)=>item.area===state.adminArea),root=areaItems.find((item)=>!item.parent_id),defaultParent=root?.id||null,defaultType=root?.item_type==="program"?"course":"lesson",courses=areaItems.filter((item)=>item.item_type==="course").length,modules=areaItems.filter((item)=>item.item_type==="module").length,lessons=areaItems.filter((item)=>item.item_type==="lesson").length;return shell(`<section class="admin-shell lms-admin-shell ${state.editing!==null?'has-inspector':''}">${adminNav("content")}<section class="admin-main course-builder"><div class="admin-toolbar builder-toolbar"><div><span class="admin-eyebrow">Контент басқару</span><h2>${escapeHtml(AREAS[state.adminArea])}</h2><p>${courses} курс · ${modules} модуль · ${lessons} сабақ</p></div><button class="primary-button builder-primary" data-action="add-child" data-parent="${defaultParent||''}" data-type="${defaultType}">+ ${escapeHtml(ITEM_TYPE_LABELS[defaultType])} қосу</button></div><div class="builder-legend"><strong>Курс құрастырушы</strong><span>Бағдарлама → Курс → Модуль → Сабақ</span><small>⠿ белгісінен ұстап, блоктарды жоғары немесе төмен жылжытыңыз</small></div><ul class="builder-tree">${friendlyAdminTree()||`<li class="builder-empty"><h3>Алғашқы курсты жасаңыз</h3><button data-action="add-child" data-parent="${defaultParent||''}" data-type="${defaultType}">+ Курс жасау</button></li>`}</ul><div class="sort-announcer" aria-live="polite"></div></section>${state.editing!==null?resourceAwareEditorPanel():""}</section>`,"admin");}
function selectOptions(name,values,current){return `<select name="${name}">${values.map(([value,label])=>`<option value="${value}" ${current===value?'selected':''}>${label}</option>`).join("")}</select>`;}
function advancedThemePage(){const s={...DEFAULT_THEME,...state.settings};return shell(`<section class="admin-shell design-workspace">${adminNav("design")}<section class="admin-main design-admin"><div class="admin-toolbar builder-toolbar"><div><span class="admin-eyebrow">Сайт редакторы</span><h2>Бүкіл сайт дизайны</h2><p>Түстерді, қаріпті, өлшемді және бет құрылымын басқарыңыз</p></div></div><form id="theme-form" class="advanced-theme-form"><div class="design-controls"><section class="design-control-group"><header><span>01</span><div><h3>Бренд және типография</h3><p>Сайт атауы мен мәтін жүйесі</p></div></header><label>Сайт атауы<input name="site_title" value="${escapeHtml(s.site_title)}" maxlength="120"/></label><div class="theme-row"><label>Негізгі шрифт${selectOptions("font_family",[["Inter","Inter"],["Manrope","Manrope"],["Arial","Arial"],["Georgia","Georgia"],["Courier New","Courier"]],s.font_family)}</label><label>Тақырып шрифті${selectOptions("heading_font",[["Inter","Inter"],["Manrope","Manrope"],["Arial","Arial"],["Georgia","Georgia"],["Courier New","Courier"]],s.heading_font)}</label><label>Мәтін өлшемі<input type="range" name="base_size" min="14" max="20" value="${s.base_size}"/><output>${s.base_size}px</output></label><label>Тақырып масштабы<input type="range" name="heading_scale" min="85" max="125" value="${s.heading_scale}"/><output>${s.heading_scale}%</output></label></div></section><section class="design-control-group"><header><span>02</span><div><h3>Түстер</h3><p>Барлық беттерге ортақ палитра</p></div></header><div class="theme-colors">${themeColorInput("background","Фон")}${themeColorInput("surface","Карточка")}${themeColorInput("text","Мәтін")}${themeColorInput("muted","Қосымша мәтін")}${themeColorInput("school","Мектеп")}${themeColorInput("university","Университет")}${themeColorInput("bridge","Көпір")}${themeColorInput("diagnostic","Диагностика")}</div></section><section class="design-control-group"><header><span>03</span><div><h3>Өлшем және аралық</h3><p>Контент ені, тығыздық және пішін</p></div></header><div class="theme-row"><label>Сайт ені<input type="range" name="content_width" min="960" max="1440" step="20" value="${s.content_width}"/><output>${s.content_width}px</output></label><label>Бүйір аралық<input type="range" name="page_gutter" min="12" max="48" value="${s.page_gutter}"/><output>${s.page_gutter}px</output></label><label>Карточка радиусы<input type="range" name="card_radius" min="8" max="40" value="${s.card_radius}"/><output>${s.card_radius}px</output></label><label>Батырма радиусы<input type="range" name="button_radius" min="6" max="28" value="${s.button_radius}"/><output>${s.button_radius}px</output></label><label>Контент тығыздығы${selectOptions("density",[["compact","Жинақы"],["comfortable","Қалыпты"],["spacious","Кең"]],s.density)}</label></div></section><section class="design-control-group"><header><span>04</span><div><h3>Компоненттер және құрылым</h3><p>Header, басты бет және карточка стилі</p></div></header><div class="theme-row"><label>Header${selectOptions("header_style",[["floating","Қалқымалы"],["solid","Тұтас"],["minimal","Минимал"]],s.header_style)}</label><label>Hero${selectOptions("hero_style",[["spotlight","Жарық акцент"],["gradient","Градиент"],["clean","Таза"]],s.hero_style)}</label><label>Карточка${selectOptions("card_style",[["glass","Әйнек"],["solid","Тұтас"],["outline","Контур"]],s.card_style)}</label><label>Басты бет құрылымы${selectOptions("home_layout",[["bento","Bento"],["balanced","Тең блоктар"],["stacked","Тізім"]],s.home_layout)}</label><label>Фон${selectOptions("background_style",[["aurora","Aurora"],["grid","Тор"],["plain","Таза"]],s.background_style)}</label><label>Көлеңке${selectOptions("shadow_style",[["none","Жоқ"],["soft","Жұмсақ"],["strong","Айқын"]],s.shadow_style)}</label></div><label class="theme-toggle"><input type="checkbox" name="visual_effects" ${s.visual_effects?'checked':''}/><span>Жеңіл анимациялар</span></label></section><p class="form-error" id="theme-error"></p><div class="theme-actions sticky-actions"><button type="button" data-action="reset-theme">Бастапқы дизайн</button><button class="primary-button" type="submit">Дизайнды жариялау</button></div></div><aside class="theme-preview advanced-preview"><div class="preview-toolbar"><strong>Алдын ала көру</strong><span>Компьютер</span></div><div class="preview-browser"><div class="preview-nav"><i></i><b>${escapeHtml(s.site_title)}</b><span>Кіру</span></div><div class="preview-hero"><small>Үздіксіз білім беру платформасы</small><h3>${escapeHtml(s.site_title)}</h3></div><div class="preview-grid"><article><span>01</span><strong>Мектеп модулі →</strong></article><article><span>02</span><strong>Университет модулі →</strong></article><button type="button">Сабақтастық көпірі →</button></div></div></aside></form></section></section>`,"admin");}
function analyticsPage(){const analytics=state.analytics||{users:[],details:[]};const cards=analytics.users.map((user)=>{const userRows=analytics.details.filter((row)=>row.user_id===user.id),tests=userRows.filter((row)=>testMetrics(row).taken),correct=tests.reduce((sum,row)=>sum+testMetrics(row).correct,0),wrong=tests.reduce((sum,row)=>sum+testMetrics(row).wrong,0),viewed=userRows.filter((row)=>(row.view_count||0)>0).length;return `<article class="analytics-user clear-analytics-user"><header><div><span>${escapeHtml(ROLE_LABELS[user.role])}</span><h3>${escapeHtml(user.display_name||user.email)}</h3><small>${escapeHtml(user.email||"")}</small></div><b>${user.average_progress||0}%<small>Орташа прогресс</small></b></header><div class="analytics-metrics"><div><span>Аяқталды</span><strong>${user.completed_count||0}</strong></div><div><span>Ашылған сабақ</span><strong>${viewed}</strong></div><div><span>Тапсырылған тест</span><strong>${tests.length}</strong></div><div class="correct"><span>Дұрыс жауап</span><strong>${correct}</strong></div><div class="wrong"><span>Қате жауап</span><strong>${wrong}</strong></div></div><time>Соңғы әрекет: ${formatDate(user.last_active)}</time></article>`;}).join("");const details=analytics.details.map((row)=>{const status=progressStatus(row),test=testMetrics(row);return `<tr><td><strong>${escapeHtml(row.display_name||row.email||"")}</strong><small>${escapeHtml(ROLE_LABELS[row.role]||"")}</small></td><td><strong>${escapeHtml(row.title||"")}</strong></td><td><span class="learning-status ${status.tone}">${status.label}</span></td><td><b>${row.progress||0}%</b></td><td class="correct-number">${test.taken?test.correct:"—"}</td><td class="wrong-number">${test.taken?test.wrong:"—"}</td><td>${test.taken?`<strong>${test.percent}%</strong><small>${test.correct}/${test.total} ұпай</small>`:`<span class="not-taken-text">Тапсырылмаған</span>`}</td><td>${row.attempt_count||0}</td><td>${row.view_count||0}</td><td>${formatDate(row.tested_at||row.last_opened)}</td></tr>`;}).join("");return shell(`<section class="admin-shell analytics-admin-shell">${adminNav("analytics")}<section class="admin-main analytics-admin"><div class="admin-toolbar builder-toolbar"><div><span class="admin-eyebrow">Пайдаланушы нәтижелері</span><h2>Оқу аналитикасы</h2><p>Сабақ, тест және белсенділік көрсеткіштері</p></div></div><section class="analytics-explainer"><div><i>✓</i><span><strong>Дұрыс жауап</strong><small>Тестте дұрыс таңдалған жауаптар</small></span></div><div><i>×</i><span><strong>Қате жауап</strong><small>Қайта қарау қажет жауаптар</small></span></div><div><i>●</i><span><strong>Аяқталды</strong><small>100% орындалған сабақтар</small></span></div></section><div class="analytics-grid">${cards||`<p class="resource-empty">Белсенділік жоқ</p>`}</div><section class="analytics-detail-section"><header><span>Толық мәлімет</span><h3>Сабақтар бойынша нәтижелер</h3></header><div class="analytics-table-wrap clear-analytics-table"><table><thead><tr><th>Пайдаланушы</th><th>Сабақ</th><th>Күйі</th><th>Прогресс</th><th>Дұрыс</th><th>Қате</th><th>Тест нәтижесі</th><th>Әрекет</th><th>Қаралым</th><th>Соңғы белсенділік</th></tr></thead><tbody>${details}</tbody></table></div></section></section></section>`,"admin");}
function adminUsersPage(){const rows=state.users.map((user)=>`<li class="admin-row user-row"><div><strong>${escapeHtml(user.display_name||user.email)}</strong><small>${escapeHtml(user.email||"")}</small></div><label>Рөл<select data-role-user="${user.id}">${Object.entries(ROLE_LABELS).map(([key,label])=>`<option value="${key}" ${user.role===key?'selected':''}>${label}</option>`).join("")}</select></label></li>`).join("");return shell(`<section class="admin-shell">${adminNav("users")}<section class="admin-main"><div class="admin-toolbar"><h2>Пайдаланушылар</h2></div><ul class="admin-list">${rows}</ul></section></section>`,"admin");}

function deleteDialog(){return `<div class="modal-backdrop"><section class="confirm-dialog" role="alertdialog" aria-modal="true"><span class="warning-mark">!</span><h2>Өшіру</h2><p>${escapeHtml(state.deleting.title)}</p><div><button data-action="cancel-delete">Бас тарту</button><button class="danger-button" data-action="confirm-delete">Өшіру</button></div></section></div>`;}
function filePreviewDialog(resource){const kind=resourceKind(resource),preview=kind==="ppt"&&resource.presentation_url?`<div class="presentation-viewer" id="presentation-viewer" data-url="${escapeHtml(resource.presentation_url)}"><div class="presentation-loading">Слайдтар жүктелуде…</div></div>`:resourcePreview(resource,false);return `<div class="file-modal-backdrop" data-action="close-preview"><section class="file-viewer" role="dialog" aria-modal="true" aria-labelledby="file-title"><header><div><span>${kind.toUpperCase()}</span><h2 id="file-title">${escapeHtml(resource.filename)}</h2><small>${formatSize(resource.size||0)}</small></div><button class="viewer-close" type="button" data-action="close-preview" aria-label="Жабу">×</button></header><div class="viewer-canvas ${kind}">${preview}</div><footer><a href="${escapeHtml(resource.url)}" target="_blank" rel="noopener">Жаңа терезеде ашу ↗</a><button class="viewer-download" data-download-resource="${resource.id}">Жүктеп алу ↓</button></footer></section></div>`;}
function notFoundPage(){return shell(`<section class="status-page"><span>404</span><h1>Бет табылмады</h1><a class="primary-button" href="/">Басты бет</a></section>`);}
