function saveRichSelection(){const selection=window.getSelection(),editor=app.querySelector("#rich-body");if(selection?.rangeCount&&editor?.contains(selection.anchorNode))savedRichRange=selection.getRangeAt(0).cloneRange();}
function applyRichCommand(event){const control=event.currentTarget,editor=app.querySelector("#rich-body"),selection=window.getSelection();if(!editor)return;event.preventDefault();editor.focus();if(savedRichRange){selection.removeAllRanges();selection.addRange(savedRichRange);}document.execCommand("styleWithCSS",false,false);document.execCommand(control.dataset.richCommand,false,control.value||null);saveRichSelection();}
