async function loadPresentationPreview(){const viewer=app.querySelector("#presentation-viewer");if(!viewer)return;try{const response=await fetch(viewer.dataset.url);if(!response.ok)throw new Error("Слайдтар ашылмады");const deck=await response.json();if(!deck.slides?.length)throw new Error("Слайдтар табылмады");viewer.innerHTML=`<div class="presentation-toolbar"><strong>${deck.slides.length} слайд</strong><div><button type="button" data-slide-nav="prev">↑</button><button type="button" data-slide-nav="next">↓</button></div></div><div class="presentation-scroll">${deck.slides.map((slide)=>`<article class="presentation-slide" id="preview-slide-${slide.number}" style="aspect-ratio:${deck.width}/${deck.height};background:${escapeHtml(slide.background)}"><span class="slide-number">${slide.number}</span>${slide.elements.map((element)=>element.type==="image"?`<img src="${escapeHtml(element.src)}" alt="" style="left:${element.x}%;top:${element.y}%;width:${element.w}%;height:${element.h}%"/>`:`<div class="slide-text" style="left:${element.x}%;top:${element.y}%;width:${element.w}%;height:${element.h}%;background:${escapeHtml(element.fill)};border-color:${escapeHtml(element.line)};color:${escapeHtml(element.color)};text-align:${element.align};font-size:clamp(7px,${Math.max(.8,Number(element.font_size||18)/7.2)}cqw,72px)">${escapeHtml(element.text).replace(/\n/g,"<br>")}</div>`).join("")}</article>`).join("")}</div>`;let current=0;const slides=[...viewer.querySelectorAll(".presentation-slide")];viewer.querySelectorAll("[data-slide-nav]").forEach((button)=>button.addEventListener("click",()=>{current=Math.max(0,Math.min(slides.length-1,current+(button.dataset.slideNav==="next"?1:-1)));slides[current].scrollIntoView({behavior:"smooth",block:"start"});}));}catch(error){viewer.innerHTML=`<div class="presentation-error">${escapeHtml(error.message)}</div>`;}}

function themeFromForm(form){const data=new FormData(form),settings={...DEFAULT_THEME,...state.settings};for(const key of ["site_title","font_family","heading_font","background","surface","text","muted","school","university","bridge","diagnostic","density","header_style","hero_style","card_style","home_layout","background_style","shadow_style"])if(data.has(key))settings[key]=String(data.get(key)||settings[key]);for(const key of ["base_size","heading_scale","card_radius","button_radius","content_width","page_gutter"])if(data.has(key))settings[key]=Number(data.get(key)||settings[key]);settings.visual_effects=data.get("visual_effects")==="on";settings.interface_version=2;return settings;}
function handleThemePreview(event){const form=event.currentTarget;if(event.target.matches('input[type="color"]')){const text=form.querySelector(`[data-color-text="${event.target.name}"]`);if(text)text.value=event.target.value;}if(event.target.matches("[data-color-text]")){const color=form.elements[event.target.dataset.colorText];if(/^#[0-9a-f]{6}$/i.test(event.target.value)&&color)color.value=event.target.value;}state.settings=themeFromForm(form);applyTheme();form.querySelectorAll('input[type="range"]').forEach((input)=>{const output=input.closest("label")?.querySelector("output");if(output)output.textContent=`${input.value}${input.name==="heading_scale"?"%":"px"}`;});const title=form.querySelector(".theme-preview h3");if(title)title.textContent=state.settings.site_title;}
