function initBuilderDragDrop(){app.querySelectorAll(".builder-row").forEach((row)=>{const id=row.querySelector('[data-action="edit"]')?.dataset.id,handle=row.querySelector(".builder-handle");if(!id||!handle)return;row.dataset.dragId=id;handle.setAttribute("tabindex","0");handle.setAttribute("role","button");handle.setAttribute("aria-label","Мышкамен жылжыту");handle.addEventListener("mousedown",()=>{row.draggable=true;});row.addEventListener("dragstart",(event)=>{draggedContentId=id;row.classList.add("dragging");event.dataTransfer.effectAllowed="move";event.dataTransfer.setData("text/plain",id);});row.addEventListener("dragover",(event)=>{const dragged=state.items.find((item)=>item.id===draggedContentId),target=state.items.find((item)=>item.id===id);if(!dragged||!target||dragged.parent_id!==target.parent_id||dragged.id===target.id)return;event.preventDefault();app.querySelectorAll(".builder-row.drop-before,.builder-row.drop-after").forEach((node)=>node.classList.remove("drop-before","drop-after"));row.classList.add(event.clientY<row.getBoundingClientRect().top+row.offsetHeight/2?"drop-before":"drop-after");});row.addEventListener("drop",async(event)=>{event.preventDefault();const after=row.classList.contains("drop-after");await reorderByDrop(draggedContentId,id,after);});row.addEventListener("dragend",()=>{draggedContentId=null;row.draggable=false;app.querySelectorAll(".builder-row").forEach((node)=>node.classList.remove("dragging","drop-before","drop-after"));});});}
async function reorderByDrop(draggedId,targetId,after){const dragged=state.items.find((item)=>item.id===draggedId),target=state.items.find((item)=>item.id===targetId);if(!dragged||!target||dragged.parent_id!==target.parent_id)return;const siblings=state.items.filter((item)=>item.area===dragged.area&&item.parent_id===dragged.parent_id).sort((a,b)=>a.sort_order-b.sort_order),ordered=siblings.filter((item)=>item.id!==draggedId),targetIndex=ordered.findIndex((item)=>item.id===targetId);ordered.splice(targetIndex+(after?1:0),0,dragged);try{await store.reorderContent(ordered.map((item)=>item.id));state.items=normalizeItems(await store.listContent(true));render();showToast("Реті сақталды");}catch(error){showToast(error.message||"Реттеу қатесі","error");}}
async function loadResources(itemId,force=false){if(!force&&state.resources[itemId])return;state.resources[itemId]=await store.listResources(itemId);}
async function hydrateRoute(){const path=routePath();const item=byPath(path);if(!item||["school-root","university-root","bridge-root"].includes(item.id))return;try{await loadResources(item.id);if(state.user&&state.user.role!=="admin"&&!state.viewed.has(item.id)){state.viewed.add(item.id);await store.recordView(item.id);state.progress=await store.getProgress();}render();}catch(error){showToast(error.message,"error");}}

document.addEventListener("selectionchange",saveRichSelection);
window.addEventListener("popstate",()=>{render();hydrateRoute();});
async function refreshCatalog(){state.allResources=await store.listAllResources();state.resources={};for(const item of state.items)state.resources[item.id]=state.allResources.filter(r=>r.item_id===item.id);if(store.mode==='local-server'||window.__CHEM_CONFIG__?.schemaVersion>=2)state.popularity=await store.listPopularity().catch(()=>[]);}
async function openResource(id,download=false){
 const resource=state.allResources.find(r=>r.id===id)||Object.values(state.resources).flat().find(r=>r.id===id);if(!resource)return showToast('Файл табылмады','error');
 try{const url=await store.resourceUrl(resource,download);if(download){showToast('Файл жүктелуде...');const response=await fetch(url+(store.mode==='local-server'?'?download=1':''),{signal:AbortSignal.timeout(60000)});if(!response.ok)throw new Error('Файлды жүктеп алу мүмкін болмады. Қайта әрекет жасаңыз');const blobUrl=URL.createObjectURL(await response.blob());const a=document.createElement('a');a.href=blobUrl;a.download=resource.filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(blobUrl),60000);showToast('Файлды жүктеп алу басталды');}else{state.previewing={...resource,url};render();}}catch(error){showToast(error.message,'error');}
}
