 if(existing){item=await store.updateContent(existing.id,{...existing,...patch,is_published:existing.is_published});}
 else{item=await store.createContent({...patch,path:'/material/'+crypto.randomUUID(),item_type:'lesson',content_mode:'resources',body:'',video_url:'',quiz_data:{},sort_order:0,is_published:false});form.dataset.id=item.id;}
 if(hasFile)await store.uploadResource(item.id,file,p=>{status.innerHTML=`<label>Жүктелуде... ${p}%<progress max="100" value="${p}"></progress></label>`;});
 if(hasFile){fileSaved=true;form.querySelector('[name="file"]').value='';}
